 * Component: Card
 * Author: @arjun-kumar (https://tailwindflex.com/@arjun-kumar)
 * Source: https://tailwindflex.com/@arjun-kumar/card-42
 * Attribution: Créé par @arjun-kumar sur TailwindFlex
 * License: Open Source (TailwindFlex community)
 */
import React from "react";

export function Card42() {
  return (
    <div dangerouslySetInnerHTML={{ __html: "<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>3D Flip Card | Premium Blur Effect</title>

    <link rel="stylesheet" href="https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.7.2/css/all.min.css">
    <style>
        @keyframes floatParticle {
            0% { transform: translateY(0) translateX(0) scale(1); opacity: 0.8; }
            100% { transform: translateY(-150px) translateX(60px) scale(0); opacity: 0; }
        }
        .particle {
            position: absolute;
            width: 8px;
            height: 8px;
            background: radial-gradient(circle, #ff6b6b, #4ecdc4, #45b7d1);
            border-radius: 50%;
            pointer-events: none;
            animation: floatParticle 3.5s infinite ease-out;
        }
        .flip-card {
            perspective: 2000px;
            transform-style: preserve-3d;
        }
        .flip-card-inner {
            transition: transform 0.8s cubic-bezier(0.68, -0.55, 0.265, 1.55);
            transform-style: preserve-3d;
        }
        .flip-card:hover .flip-card-inner {
            transform: rotateY(180deg);
        }
        .flip-front, .flip-back {
            backface-visibility: hidden;
            -webkit-backface-visibility: hidden;
        }
        .flip-back {
            transform: rotateY(180deg);
        }
        .glow-rare {
            transition: all 0.4s;
            background: rgba(255,255,255,0.15);
            backdrop-filter: blur(10px);
        }
        .glow-rare:hover {
            background: rgba(255,255,255,0.35);
            box-shadow: 0 0 30px rgba(78,205,196,0.8);
            transform: scale(1.05);
        }
        .blur-overlay {
            backdrop-filter: blur(8px);
        }
    </style>
</head>
<body class="bg-gradient-to-br from-gray-900 via-purple-900 to-gray-900 flex items-center justify-center min-h-screen overflow-hidden relative">

    <div class="absolute inset-0 bg-[url('https://www.transparenttextures.com/patterns/stardust.png')] opacity-20"></div>

    <div class="relative flip-card w-96 h-[32rem]">
        <div class="flip-card-inner relative w-full h-full">
            <div class="flip-front absolute w-full h-full rounded-2xl shadow-2xl overflow-hidden">
                <div class="absolute inset-0 bg-gradient-to-br from-blue-600 via-purple-600 to-pink-600 opacity-90"></div>
                <img src="https://picsum.photos/id/104/500/500" class="absolute inset-0 w-full h-full object-cover opacity-40">
                <div class="relative z-10 flex flex-col items-center justify-center h-full text-white">
                    <i class="fa-solid fa-gem text-6xl mb-4" style="color: #ffd700;"></i>
                    <h2 class="text-3xl font-black tracking-wider mb-2">PREMIUM CARD</h2>
                    <div class="w-20 h-1 bg-white/50 rounded-full my-4"></div>
                    <p class="text-lg opacity-90 flex items-center gap-2">
                        <i class="fa-solid fa-hand-pointer text-sm"></i> Hover to Flip
                    </p>
                </div>
            </div>
            <div class="flip-back absolute w-full h-full rounded-2xl shadow-2xl overflow-hidden">
                <div class="absolute inset-0 bg-gradient-to-br from-emerald-600 via-teal-600 to-cyan-600"></div>
                <img src="https://picsum.photos/id/106/500/500" class="absolute inset-0 w-full h-full object-cover opacity-30 blur-sm">
                <div class="relative z-10 flex flex-col items-center justify-center h-full text-white p-6 text-center blur-overlay bg-black/20">
                    <div class="relative">
                        <img src="https://picsum.photos/id/100/100/100" class="w-24 h-24 rounded-full object-cover border-4 border-white shadow-2xl mb-4">
                        <i class="fa-solid fa-circle-check absolute -bottom-1 -right-1 text-2xl bg-white rounded-full text-green-500 p-1"></i>
                    </div>
                    <h3 class="text-2xl font-bold mb-2">Amazing Creation</h3>
                    <p class="text-sm opacity-90 mb-4">This is my unique card with blur effect</p>
                    <button class="mt-2 px-6 py-2 rounded-full backdrop-blur-md glow-rare transition font-semibold flex items-center gap-2 mx-auto">
                        <i class="fa-regular fa-hand-peace"></i> Interact Now
                    </button>
                </div>
            </div>
        </div>
    </div>


</body>
</html>" }} />
  );
}
